node -e '
const pricing = {
  on_demand_vcpu_hour: 0.0335,
  on_demand_gib_hour: 0.0045,
  spot_discount_fraction: 0.70
};
const spot_multiplier = 1.0 - pricing.spot_discount_fraction; // 0.30
const HOURS = 730;

const workloads_initial = [
  { name: "payments-api", replicas: 2, cpu: 0.5, mem: 512/1024, tier: "critical" },
  { name: "image-resizer", replicas: 3, cpu: 0.5, mem: 256/1024, tier: "batch" },
  { name: "report-builder", replicas: 2, cpu: 1.0, mem: 1024/1024, tier: "batch" },
  { name: "log-shipper", replicas: 2, cpu: 0.1, mem: 128/1024, tier: "batch" },
  { name: "session-store", replicas: 1, cpu: 0.1, mem: 256/1024, tier: "critical" }
];

const workloads_optimized = [
  { name: "payments-api", replicas: 2, cpu: 0.15, mem: 192/1024, tier: "critical" },
  { name: "image-resizer", replicas: 3, cpu: 0.10, mem: 128/1024, tier: "batch" },
  { name: "report-builder", replicas: 2, cpu: 0.20, mem: 256/1024, tier: "batch" },
  { name: "log-shipper", replicas: 2, cpu: 0.10, mem: 128/1024, tier: "batch" },
  { name: "session-store", replicas: 1, cpu: 0.10, mem: 256/1024, tier: "critical" }
];

function calc(w_list, useSpot) {
  let totalCpu = 0, totalMem = 0, totalCostMo = 0, totalCpuCost = 0, totalMemCost = 0;
  const details = [];
  for (const w of w_list) {
    const cores = w.replicas * w.cpu;
    const memGib = w.replicas * w.mem;
    const isSpot = useSpot && (w.tier === "batch");
    const mult = isSpot ? spot_multiplier : 1.0;
    const cpuHr = cores * pricing.on_demand_vcpu_hour * mult;
    const memHr = memGib * pricing.on_demand_gib_hour * mult;
    const costHr = cpuHr + memHr;
    const costMo = costHr * HOURS;
    totalCpu += cores;
    totalMem += memGib;
    totalCpuCost += cpuHr * HOURS;
    totalMemCost += memHr * HOURS;
    totalCostMo += costMo;
    details.push({
      name: w.name,
      tier: w.tier,
      isSpot,
      replicas: w.replicas,
      cpuPerPod: w.cpu,
      memPerPod: w.mem,
      totalCpu: cores,
      totalMem: memGib,
      costHr,
      costMo
    });
  }
  return { totalCpu, totalMem, totalCpuCost, totalMemCost, totalCostMo, details };
}

console.log("Initial (All On-Demand):", calc(workloads_initial, false));
console.log("Rightsized (All On-Demand):", calc(workloads_optimized, false));
console.log("Rightsized + Spot for Batch:", calc(workloads_optimized, true));
'

