node -e '
const fs = require("fs");

const pricing = {
  on_demand_vcpu_hour: 0.0335,
  on_demand_gib_hour: 0.0045,
  spot_discount_fraction: 0.70
};
const spot_multiplier = 0.30;
const HOURS = 730;

const initial = [
  { name: "payments-api", replicas: 2, cpu: 0.5, memMiB: 512, tier: "critical", isSpot: false },
  { name: "image-resizer", replicas: 3, cpu: 0.5, memMiB: 256, tier: "batch", isSpot: false },
  { name: "report-builder", replicas: 2, cpu: 1.0, memMiB: 1024, tier: "batch", isSpot: false },
  { name: "log-shipper", replicas: 2, cpu: 0.1, memMiB: 128, tier: "batch", isSpot: false },
  { name: "session-store", replicas: 1, cpu: 0.1, memMiB: 256, tier: "critical", isSpot: false }
];

const rightsized_ondemand = [
  { name: "payments-api", replicas: 2, cpu: 0.15, memMiB: 192, tier: "critical", isSpot: false },
  { name: "image-resizer", replicas: 3, cpu: 0.10, memMiB: 128, tier: "batch", isSpot: false },
  { name: "report-builder", replicas: 2, cpu: 0.20, memMiB: 256, tier: "batch", isSpot: false },
  { name: "log-shipper", replicas: 2, cpu: 0.10, memMiB: 128, tier: "batch", isSpot: false },
  { name: "session-store", replicas: 1, cpu: 0.10, memMiB: 256, tier: "critical", isSpot: false }
];

const final_optimized = [
  { name: "payments-api", replicas: 2, cpu: 0.15, memMiB: 192, tier: "critical", isSpot: false },
  { name: "image-resizer", replicas: 3, cpu: 0.10, memMiB: 128, tier: "batch", isSpot: true },
  { name: "report-builder", replicas: 2, cpu: 0.20, memMiB: 256, tier: "batch", isSpot: true },
  { name: "log-shipper", replicas: 2, cpu: 0.10, memMiB: 128, tier: "batch", isSpot: true },
  { name: "session-store", replicas: 1, cpu: 0.10, memMiB: 256, tier: "critical", isSpot: false }
];

function summarize(list) {
  let totalCpu = 0, totalMemGiB = 0, costHr = 0, costMo = 0;
  const rows = list.map(item => {
    const totalItemCpu = item.replicas * item.cpu;
    const totalItemMemGiB = item.replicas * (item.memMiB / 1024);
    const rate = item.isSpot ? spot_multiplier : 1.0;
    const itemCostHr = (totalItemCpu * pricing.on_demand_vcpu_hour + totalItemMemGiB * pricing.on_demand_gib_hour) * rate;
    const itemCostMo = itemCostHr * HOURS;
    totalCpu += totalItemCpu;
    totalMemGiB += totalItemMemGiB;
    costHr += itemCostHr;
    costMo += itemCostMo;
    return {
      ...item,
      totalItemCpu,
      totalItemMemGiB,
      itemCostHr,
      itemCostMo
    };
  });
  return { totalCpu, totalMemGiB, costHr, costMo, rows };
}

const sumInit = summarize(initial);
const sumRightsized = summarize(rightsized_ondemand);
const sumFinal = summarize(final_optimized);

console.log("Baseline Monthly Spend: $" + sumInit.costMo.toFixed(2));
console.log("Rightsized (On-Demand) Spend: $" + sumRightsized.costMo.toFixed(2) + " (" + ((1 - sumRightsized.costMo/sumInit.costMo)*100).toFixed(1) + "% reduction)");
console.log("Final (Rightsized + Spot) Spend: $" + sumFinal.costMo.toFixed(2) + " (" + ((1 - sumFinal.costMo/sumInit.costMo)*100).toFixed(1) + "% reduction)");
'
